cat > main.go <<'EOF'
package main

import (
	"encoding/json"
	"fmt"
	"slices"
	"time"
)

// Mirrors the real session.TaskRecord tags (omitempty on CompletedAt).
type taskRecord struct {
	ToolUseID   string    `json:"tool_use_id"`
	AgentID     string    `json:"agent_id,omitempty"`
	Files       []string  `json:"files,omitempty"`
	CompletedAt time.Time `json:"completed_at,omitempty"`
}
type state struct {
	TaskRecords []taskRecord `json:"task_records,omitempty"`
}

// The helper's decode shape + predicate, verbatim in spirit.
type decoded struct {
	TaskRecords []struct {
		ToolUseID   string    `json:"tool_use_id"`
		AgentID     string    `json:"agent_id"`
		Files       []string  `json:"files"`
		CompletedAt time.Time `json:"completed_at"`
	} `json:"task_records"`
}

func matches(raw []byte, wantFile string) bool {
	var d decoded
	if err := json.Unmarshal(raw, &d); err != nil {
		return false
	}
	for _, rec := range d.TaskRecords {
		if rec.CompletedAt.IsZero() {
			continue
		}
		if slices.Contains(rec.Files, wantFile) {
			return true
		}
	}
	return false
}

func main() {
	want := "docs/factory-hook-check.md"
	cases := []struct {
		name string
		s    state
		want bool
	}{
		{"in-flight, no files", state{[]taskRecord{{ToolUseID: "t1"}}}, false},
		{"in-flight, files already set", state{[]taskRecord{{ToolUseID: "t1", Files: []string{want}}}}, false},
		{"completed, wrong file", state{[]taskRecord{{ToolUseID: "t1", Files: []string{"docs/other.md"}, CompletedAt: time.Now()}}}, false},
		{"completed, no files (read-only subagent)", state{[]taskRecord{{ToolUseID: "t1", CompletedAt: time.Now()}}}, false},
		{"completed with the file", state{[]taskRecord{{ToolUseID: "t1", AgentID: "w1", Files: []string{want}, CompletedAt: time.Now()}}}, true},
		{"unrelated completed + ours completed", state{[]taskRecord{
			{ToolUseID: "other", Files: []string{"docs/x.md"}, CompletedAt: time.Now()},
			{ToolUseID: "t1", Files: []string{want}, CompletedAt: time.Now()},
		}}, true},
		{"no records at all", state{}, false},
	}
	ok := true
	for _, c := range cases {
		raw, _ := json.Marshal(c.s)
		got := matches(raw, want)
		status := "PASS"
		if got != c.want {
			status, ok = "FAIL", false
		}
		fmt.Printf("%-45s want=%-5v got=%-5v %s\n", c.name, c.want, got, status)
	}
	if !ok {
		panic("predicate check failed")
	}
	fmt.Println("\nall predicate cases behave correctly")
}
EOF
